/**
 * WF7 Phase4: Creatomate RenderScript生成ロジック（単体テスト用）
 *
 * 作成日時: 2025-11-16 10:30:37 JST
 *
 * 目的:
 * 統合モックデータ（Phase1/2/3を含む単一JSON）から、
 * Creatomate APIに送信するRenderScriptを動的に生成する。
 *
 * 入力:
 * - $input.first().json.Phase1.Script: Script JSON（7セグメント構成）
 * - $input.first().json.Phase2.Assets: 画像データ配列（assetTag → originalUrl）
 * - $input.first().json.Phase3.Audio: 音声・字幕データ（assetTag → audioUrl）
 *
 * 出力:
 * - renderScript: Creatomate RenderScript JSON
 */

// ===========================
// 1. 入力データの取得と検証
// ===========================

// 統合モックデータから各Phaseのデータを取得
const phase1Data = $input.first().json.Phase1;
const phase2Data = $input.first().json.Phase2;
const phase3Data = $input.first().json.Phase3;

// Phase1: Script JSON（7セグメント構成）
const scriptData = phase1Data.Script;
if (!scriptData || !scriptData.segments || !Array.isArray(scriptData.segments)) {
  throw new NodeOperationError(
    this.getNode(),
    'Phase1のScript JSONが不正です。segments配列が見つかりません。'
  );
}

const segments = scriptData.segments;
if (segments.length === 0) {
  throw new NodeOperationError(
    this.getNode(),
    'Phase1のScript JSONにセグメントが含まれていません。'
  );
}

// Phase2: 画像データ配列
const assetsData = phase2Data.Assets;
if (!assetsData || !Array.isArray(assetsData)) {
  throw new NodeOperationError(
    this.getNode(),
    'Phase2のAssets JSONが不正です。Assets配列が見つかりません。'
  );
}

// Phase3: 音声・字幕データ
const audioData = phase3Data.Audio;
if (!audioData || !audioData.segments || !Array.isArray(audioData.segments)) {
  throw new NodeOperationError(
    this.getNode(),
    'Phase3のAudio JSONが不正です。segments配列が見つかりません。'
  );
}

// ===========================
// 2. assetTagベースのマッピング
// ===========================

// Phase2: assetTag → Asset（画像データ）のマップを作成
const assetMap = {};
assetsData.forEach(asset => {
  if (asset.assetTag) {
    assetMap[asset.assetTag] = asset;
  }
});

// Phase3: assetTag → AudioSegment（音声データ）のマップを作成
const audioMap = {};
audioData.segments.forEach(audioSegment => {
  if (audioSegment.assetTag) {
    audioMap[audioSegment.assetTag] = audioSegment;
  }
});

// ===========================
// 3. RenderScript elements配列の生成
// ===========================

const elements = [];
const trackImage = 1;
const trackText = 2;
const trackAudio = 3;

let currentTime = 0; // 現在の時間（秒）

segments.forEach((segment, index) => {
  const { type, duration, subtitle, assetTag } = segment;

  // 必須フィールドの検証
  if (!assetTag) {
    throw new NodeOperationError(
      this.getNode(),
      `セグメント${index + 1}（type: ${type}）にassetTagが設定されていません。`
    );
  }

  if (!duration || duration <= 0) {
    throw new NodeOperationError(
      this.getNode(),
      `セグメント${index + 1}（assetTag: ${assetTag}）のdurationが不正です: ${duration}`
    );
  }

  // Phase2から画像データを取得
  const asset = assetMap[assetTag];
  if (!asset) {
    throw new NodeOperationError(
      this.getNode(),
      `assetTag="${assetTag}"に対応する画像データがPhase2に見つかりません。`
    );
  }

  // 画像URL（originalUrlを優先、なければエラー）
  const imageUrl = asset.originalUrl || asset.cloudinaryUrl;
  if (!imageUrl) {
    throw new NodeOperationError(
      this.getNode(),
      `assetTag="${assetTag}"の画像URLが見つかりません。originalUrlまたはcloudinaryUrlを設定してください。`
    );
  }

  // Phase3から音声データを取得
  const audioSegment = audioMap[assetTag];
  if (!audioSegment) {
    throw new NodeOperationError(
      this.getNode(),
      `assetTag="${assetTag}"に対応する音声データがPhase3に見つかりません。`
    );
  }

  const audioUrl = audioSegment.audioUrl;
  if (!audioUrl) {
    throw new NodeOperationError(
      this.getNode(),
      `assetTag="${assetTag}"の音声URLが見つかりません。`
    );
  }

  // 字幕テキスト（Phase3にあればそれを使用、なければPhase1のsubtitleを使用）
  const subtitleText = audioSegment.subtitle || subtitle;
  if (!subtitleText) {
    throw new NodeOperationError(
      this.getNode(),
      `assetTag="${assetTag}"の字幕テキストが見つかりません。`
    );
  }

  // ------------------------------
  // 要素1: 背景画像（Ken Burns効果付き）
  // ------------------------------
  elements.push({
    type: "image",
    source: imageUrl,
    track: trackImage,
    time: currentTime,
    duration: duration,
    animations: [
      {
        type: "scale",
        start_scale: "120%",
        end_scale: "100%",
        duration: duration,
        easing: "cubic-in-out",
        scope: "element"
      }
    ]
  });

  // ------------------------------
  // 要素2: 日本語字幕テキスト
  // ------------------------------
  elements.push({
    type: "text",
    text: subtitleText,
    font_family: "Noto Sans JP",
    font_size: "60 px",
    color: "#FFFFFF",
    y: "50%",
    x: "50%",
    x_anchor: "50%",
    y_anchor: "50%",
    track: trackText,
    time: currentTime,
    duration: duration
  });

  // ------------------------------
  // 要素3: 音声（TTS生成音声）
  // ------------------------------
  elements.push({
    type: "audio",
    source: audioUrl,
    track: trackAudio,
    time: currentTime,
    duration: duration
  });

  // 次のセグメントの開始時間を更新
  currentTime += duration;
});

// ===========================
// 4. RenderScript JSONの構築
// ===========================

const totalDuration = currentTime; // 合計時間

const renderScript = {
  template_id: "40ff626c-9e09-4769-b8b9-66e859ecafa9",
  modifications: {
    output_format: "mp4",
    width: 1080,
    height: 1920,
    duration: totalDuration,
    elements: elements
  }
};

// ===========================
// 5. 出力
// ===========================

return {
  renderScript: renderScript,
  metadata: {
    totalSegments: segments.length,
    totalDuration: totalDuration,
    totalElements: elements.length,
    generatedAt: new Date().toISOString()
  }
};

/**
 * カウンター初期化
 * 
 * Creatomate APIレスポンスからrender IDを抽出し、
 * ポーリングカウンターを初期化する
 */

const renderId = $json.id;

if (!renderId) {
  throw new NodeOperationError(
    this.getNode(),
    'Creatomate APIレスポンスにrender IDが見つかりません。'
  );
}

return {
  renderId: renderId,
  pollCounter: 0,
  maxPolls: 60,
  status: 'rendering',
  originalResponse: $json
};

/**
 * カウンターインクリメント＆ステータス保持
 * 
 * ポーリング回数をカウントアップし、
 * Creatomateから取得したステータスを保持する
 */

const currentCounter = $('Init Polling Counter').item.json.pollCounter;
const maxPolls = $('Init Polling Counter').item.json.maxPolls;
const renderId = $('Init Polling Counter').item.json.renderId;

const renderStatus = $json.status;
const renderUrl = $json.url || null;

return {
  renderId: renderId,
  pollCounter: currentCounter + 1,
  maxPolls: maxPolls,
  status: renderStatus,
  url: renderUrl,
  renderData: $json
};

/**
 * Step 4: 動画URL抽出 + Notion更新準備（単体テスト用）
 *
 * Creatomate APIのレスポンスから動画URLを抽出し、
 * Notion Hub更新用のデータを準備する
 */

// 動画URLを抽出
const videoUrl = $json.url;

if (!videoUrl) {
  throw new NodeOperationError(
    this.getNode(),
    'レンダリング成功レスポンスに動画URLが見つかりません。'
  );
}

// Notion更新用のデータを準備
// 統合モックデータからTaskIDとTitleを取得
const taskId = $input.first().json.Phase1.TaskID || null;
const title = $input.first().json.Phase1.Script?.title || 'WF7 自動生成動画';

return {
  videoUrl: videoUrl,
  taskId: taskId,
  title: title,
  status: 'Phase4完了',
  completedAt: new Date().toISOString()
};
